const managementDescriptions={'Empresa':'Identidad, dirección y datos del negocio.','Series':'Numeración de documentos y series.','Locales':'Establecimientos vinculados a los puestos.','Plantillas de ticket':'Diseño y contenido de documentos impresos.','Plantillas de etiquetas':'Formatos para etiquetado de productos.','Grupos de periodos de servicio':'Franjas y turnos del servicio.','Tipos de clientes':'Clasificación de clientes.','Clientes':'Fichas y vinculación de ventas a clientes.','Grupos de puntos de venta':'Agrupación de terminales.','Puntos de venta':'Registro y conexión de terminales.','Administración web':'Acceso remoto; actualmente solo funciona en este equipo.','Grupos mayores':'Un nivel adicional de agrupación de familias.','Menús':'Composición y elecciones de menús.','Alérgenos':'Asignación de alérgenos a productos.','Etiquetas de productos':'Clasificación mediante etiquetas.','Tarifas':'Precios alternativos por centro y servicio.','Promociones':'Reglas promocionales aplicadas al vender.','Descuentos':'Reglas y permisos para descuentos.','Plantillas de comandas':'Diseño de comandas para impresoras.','Notas de preparación':'Listado reutilizable de notas; actualmente se escribe una nota libre por línea en el TPV.','Motivos de cancelación':'Motivos y registro de anulaciones.','Plantillas de entradas':'Plantillas reutilizables para recepciones de mercancía.','Entradas':'Emisión y control de entradas.'};
function adminBack(label='Administración'){return `<button class="button secondary" data-admin-back>← ${esc(label)}</button>`}
function metric(label,value,sub){return `<article class="insight-metric"><span>${esc(label)}</span><strong>${value}</strong><small>${esc(sub)}</small></article>`}
function barChart(rows,labelIndex,valueIndex){if(!rows.length)return empty('Sin operaciones en este periodo','Los resultados aparecerán cuando se registren ventas.');const max=Math.max(1,...rows.map(r=>r[valueIndex]));return `<div class="rank-chart">${rows.slice(0,10).map(r=>`<div class="rank-item"><div><span>${esc(r[labelIndex])}</span><b>${euro(r[valueIndex])}</b></div><div class="rank-track"><i style="width:${Math.max(0,r[valueIndex]/max*100)}%"></i></div></div>`).join('')}</div>`}
function trendChart(rows){if(!rows.length||!rows.some(r=>r[1]||r[3]))return empty('Aún no hay ventas cerradas','La gráfica utiliza las fechas de cierre de las cuentas.');const current=rows.map(r=>r[1]),previous=rows.map(r=>r[3]||0),max=Math.max(1,...current,...previous),w=900,h=220;const points=v=>v.map((n,i)=>`${30+i*(w-60)/Math.max(1,v.length-1)},${h-30-n*(h-60)/max}`).join(' ');return `<div class="trend-key"><span>● Periodo seleccionado</span>${rows[0].length>2?'<span class="previous">● Año anterior</span>':''}</div><svg class="trend-plot" viewBox="0 0 ${w} ${h}" role="img" aria-label="Evolución de ventas. Los valores exactos están en el informe exportable."><path d="M30 25V190H870" fill="none" stroke="#d3e3de"/><text x="32" y="18">${esc(euro(max))}</text>${rows[0].length>2?`<polyline points="${points(previous)}" fill="none" stroke="#95a6bd" stroke-width="3" stroke-dasharray="7 7"/>`:''}<polyline points="${points(current)}" fill="none" stroke="#147d64" stroke-width="4"/>${current.length===1?`<circle cx="30" cy="${h-30-current[0]*(h-60)/max}" r="5" fill="#147d64"/>`:''}<text x="30" y="214">${esc(rows[0][0])}</text><text x="775" y="214">${esc(rows.at(-1)[0])}</text></svg>`}
async function renderDashboard(){const request=++homeRequest;$('#main').innerHTML='<div class="loading-panel">Consultando tu negocio…</div>';try{const data=await api('analytics/dashboard');if(view!=='home'||request!==homeRequest)return;dashboardData=data;const period=data.cards[dashboardPeriod];const [daily,payments,categories,centers]=await Promise.all(['Comparativa interanual','Formas de pago','Categorías y productos','Centros de venta'].map(id=>fetchReport(id,period.start,period.end)));if(view!=='home'||request!==homeRequest)return;const categoryTotals={};categories.rows.forEach(r=>categoryTotals[r[0]]=(categoryTotals[r[0]]||0)+r[3]);const grouped=Object.entries(categoryTotals).sort((a,b)=>b[1]-a[1]);const sales=period.sales;$('#main').innerHTML=`<section class="insight-hero"><div><span class="eyebrow">MARCHAN2 / VISTA GENERAL</span><h2>Todo tu negocio.<br>Una mirada clara.</h2><p>Ventas cerradas y cobros, cada uno en su lugar.</p></div><div class="hero-stamp"><span>DATOS DEL EQUIPO</span><b>${esc(new Date(data.generated).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'}))}</b><button class="button secondary" id="dashboard-refresh">Actualizar</button></div></section><section class="period-metrics">${data.cards.map((p,i)=>`<button class="period-metric ${i===dashboardPeriod?'chosen':''}" data-period="${i}"><span>${p.name} ↗</span><strong>${euro(p.sales)}</strong><small>${p.tickets} cuentas cerradas · ${euro(p.collected)} cobrado</small></button>`).join('')}</section><div class="insight-strip">${metric('Cuenta media',euro(period.tickets?Math.round(sales/period.tickets):0),period.name)}${metric('Mesas ocupadas',`${data.occupied} <small>/ ${data.tables}</small>`,'Estado actual · no mide comensales')}${metric('Pendiente de cobro',euro(data.pending),'Todas las cuentas abiertas')}${metric('Almacén manual',euro(data.stock.current),'Valorado al último coste de recepción')}</div><section class="insight-panel"><div class="section-title"><div><span class="eyebrow">RITMO DEL NEGOCIO</span><h2>${esc(period.name)} frente al año anterior</h2></div><button class="button secondary" data-open-report="Comparativa interanual">Ver datos →</button></div>${trendChart(daily.rows)}<p class="muted">${esc(period.start)} → ${esc(period.end)} · Ventas con IVA. Semana desde el lunes.</p></section><div class="insight-columns"><section class="insight-panel"><span class="eyebrow">CÓMO TE PAGAN</span><h2>Cobros por método</h2>${barChart(payments.rows,0,2)}<p class="muted">Incluye cobros parciales de cuentas abiertas.</p><button class="button secondary" data-open-report="Formas de pago">Consultar cobros →</button></section><section class="insight-panel"><span class="eyebrow">QUÉ SE VENDE</span><h2>Categorías protagonistas</h2>${barChart(grouped,0,1)}<p class="muted">Agrupación actual de los productos. Márgenes no disponibles hasta registrar costes.</p><button class="button secondary" data-open-report="Categorías y productos">Explorar productos →</button></section></div><section class="insight-panel"><span class="eyebrow">MERCANCÍAS REGISTRADAS</span><h2>Valoración del almacén manual</h2><div class="insight-strip">${metric("Actual",euro(data.stock.current),"Al último coste de recepción")}${metric("Inicio de mes",euro(data.stock.month),"Saldo antes del primer día")}${metric("Inicio de año",euro(data.stock.year),"Saldo antes del primer día")}</div><p class="muted">Las ventas del TPV no descuentan este almacén automáticamente. Esta valoración requiere registrar todas las salidas y mermas.</p></section><section class="insight-panel"><span class="eyebrow">TUS ESPACIOS</span><h2>Ventas por centro</h2>${barChart(centers.rows,0,2)}<p class="muted">Centros de venta del equipo, no establecimientos independientes.</p></section>`;$('#dashboard-refresh').onclick=renderDashboard}catch(e){if(view==='home'&&request===homeRequest)$('#main').innerHTML=empty('No se pudieron cargar los informes',e.message)}}
function fetchReport(id,start=reportStart,end=reportEnd){return api('analytics/report?'+new URLSearchParams({id,start,end}))}
async function renderReportHub(){try{if(!reportEntries.length)reportEntries=await api('analytics/catalog');if(view!=='reports')return;if(selectedReport){renderReportFrame();return}const groups=[...new Set(reportEntries.map(r=>r.group))];$('#main').innerHTML=`<section class="insight-hero compact"><div><span class="eyebrow">BIBLIOTECA DE INFORMES</span><h2>Encuentra la respuesta.</h2><p>${reportEntries.filter(r=>r.available).length} informes disponibles · El resto indica los datos que faltan.</p></div></section><div class="report-controls"><input id="report-search" placeholder="Buscar informe…" value="${esc(reportSearch)}" aria-label="Buscar informe"><select id="report-group" aria-label="Grupo de informes"><option value="">Todas las áreas</option>${groups.map(g=>`<option ${g===reportGroup?'selected':''}>${esc(g)}</option>`).join('')}</select></div><div id="report-directory"></div>`;drawReportDirectory();$('#report-search').oninput=e=>{reportSearch=e.target.value;drawReportDirectory()};$('#report-group').onchange=e=>{reportGroup=e.target.value;drawReportDirectory()}}catch(e){toast(e.message,true)}}
function drawReportDirectory(){const list=reportEntries.filter(r=>(!reportGroup||r.group===reportGroup)&&r.name.toLocaleLowerCase().includes(reportSearch.toLocaleLowerCase()));$('#report-directory').innerHTML=[...new Set(list.map(r=>r.group))].map(g=>`<section class="directory-section"><h2>${esc(g)}</h2><div class="directory-grid">${list.filter(r=>r.group===g).map(r=>`<button class="directory-tile" data-open-report="${esc(r.id)}"><span class="status-pill ${r.available?'ready':'planned'}">${r.available?'DISPONIBLE':'MÓDULO PENDIENTE'}</span><strong>${esc(r.name)}</strong><span>${r.available?'Consultar y exportar CSV ↗':'Ver requisitos →'}</span></button>`).join('')}</div></section>`).join('')||empty('No hay coincidencias','Prueba con otro nombre.')}
async function renderReportFrame(){const request=++reportRequest;const id=selectedReport;$('#main').innerHTML=`<div class="section-title"><div><span class="eyebrow">INFORMES</span><h2>${esc(id)}</h2></div><button class="button secondary" id="back-reports">← Todos los informes</button></div><form id="report-range" class="report-controls"><label>DESDE<input type="date" id="report-start" value="${reportStart}" required></label><label>HASTA<input type="date" id="report-end" value="${reportEnd}" required></label><button class="button primary">Consultar</button><button type="button" class="button secondary" id="export-report" disabled>Exportar CSV</button></form><div id="report-result" class="insight-panel">Consultando…</div>`;$('#back-reports').onclick=()=>{selectedReport='';renderReportHub()};$('#report-range').onsubmit=e=>{e.preventDefault();reportStart=$('#report-start').value;reportEnd=$('#report-end').value;renderReportFrame()};try{const data=await fetchReport(id);if(view!=='reports'||id!==selectedReport||request!==reportRequest)return;reportData=data;$('#report-result').innerHTML=data.available?`<p class="report-note">${esc(data.note)}</p><p class="muted">${data.rows.length} filas · ${esc(data.start)} → ${esc(data.end)}</p>${['Evolución de ventas','Comparativa interanual','Ventas diarias'].includes(id)?trendChart(data.rows):''}<div class="scroll-table">${reportTable(data)}</div>`:`<div class="module-pending"><span class="status-pill planned">MÓDULO PENDIENTE</span><h2>Este informe necesita más datos.</h2><p>${esc(data.note)}</p><p>No se han sustituido los datos que faltan por importes de cero.</p></div>`;$('#export-report').disabled=!data.available;$('#export-report').onclick=()=>exportReport(data)}catch(e){if(view==='reports'&&request===reportRequest)$('#report-result').innerHTML=empty('No se pudo consultar',e.message)}}
function reportTable(data){return data.rows.length?`<table class="admin-table"><thead><tr>${data.columns.map(c=>`<th>${esc(c[0])}</th>`).join('')}</tr></thead><tbody>${data.rows.map(r=>`<tr>${r.map((v,i)=>`<td>${data.columns[i][1]==='money'?euro(v):esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table>`:empty('Sin registros para mostrar','Registra operaciones en el módulo correspondiente o revisa las fechas.')}
function exportReport(data){const safe=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};const content=[data.columns.map(c=>c[0]),...data.rows.map(r=>r.map((v,i)=>data.columns[i][1]==='money'?(v/100).toFixed(2).replace('.',','):v))].map(r=>r.map(safe).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+content],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`Marchan2_${data.name.replace(/[^a-z0-9]/gi,'_')}_${data.start||'actual'}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function renderManagement(){$('#main').innerHTML=`<section class="insight-hero compact"><div><span class="eyebrow">CENTRO DE ADMINISTRACIÓN</span><h2>Cada pieza, en su sitio.</h2><p>Acceso a la configuración disponible y al alcance de los módulos pendientes.</p></div></section><div class="report-controls"><input id="management-search" placeholder="Buscar configuración…" aria-label="Buscar configuración"></div><div id="management-directory"></div>`;const draw=q=>{$('#management-directory').innerHTML=Object.entries(managementGroups).map(([g,names])=>{const items=names.filter(n=>n.toLocaleLowerCase().includes(q.toLocaleLowerCase()));return items.length?`<section class="directory-section"><h2>${esc(g)}</h2><div class="directory-grid">${items.map(n=>`<button class="directory-tile" data-module="${esc(n)}"><span class="status-pill ${managementRoutes[n]?'ready':'planned'}">${managementRoutes[n]?'DISPONIBLE':'MÓDULO PENDIENTE'}</span><strong>${esc(n)}</strong><span>${managementRoutes[n]?'Abrir →':'Consultar alcance →'}</span></button>`).join('')}</div></section>`:''}).join('')||empty('No hay coincidencias')};draw('');$('#management-search').oninput=e=>draw(e.target.value)}
function openManagementModule(name){const route=managementRoutes[name];if(['users','catalog','settings'].includes(route)){go(route);$('#main').insertAdjacentHTML('afterbegin',adminBack());return}if(!route){openModal(modalTitle(name,'Módulo pendiente de implementación')+`<div class="module-pending"><p>${esc(managementDescriptions[name]||'Este módulo aún no está conectado al servicio de venta.')}</p><p>Este acceso define el apartado solicitado. Todavía no permite guardar configuración ni afecta a las ventas.</p></div><div class="form-actions"><button class="button primary" data-close>Entendido</button></div>`);return}let columns=[],rows=[],note='';if(route==='categories'||route==='families'){columns=[['Familia','text'],['Categoría','text'],['Productos activos','number']];rows=state.categories.map(c=>[c.parent,c.name,state.products.filter(p=>p.category_id===c.id).length]);note='Las familias se crean al indicar la familia padre de una nueva categoría.'}if(route==='profiles'){columns=[['Perfil','text'],['Acceso','text']];rows=[['ADMINISTRADOR','TPV y Administración'],['EQUIPO','Solo TPV']];note='Estos perfiles son fijos. Asigna el perfil desde Usuarios.'}if(route==='taxes'){columns=[['IVA %','number'],['Productos activos','number']];rows=[0,4,10,21].map(t=>[t,state.products.filter(p=>p.tax===t).length]);note='Tipos disponibles en esta versión. Se asignan en la ficha del producto; no hay editor de tipos personalizados.'}if(route==='methods'){columns=[['Método','text'],['Funcionamiento','text']];rows=[['EFECTIVO','Importe recibido y cambio'],['TARJETA','Registro manual; no procesa el cobro']];note='Métodos fijos de esta versión; admiten pagos parciales y combinados.'}if(route==='prep'||route==='courses'){columns=[['Nombre','text'],['Productos activos','number']];rows=(route==='prep'?['BARRA','COCINA']:['PRIMERO','SEGUNDO','TERCEROS','BEBIDAS','POSTRES']).map(n=>[n,state.products.filter(p=>p[route==='prep'?'prep':'course']===n).length]);note='Valores disponibles. Se asignan desde la ficha del producto; en el TPV puedes cambiar el orden de una línea.'}if(route==='monitors'){columns=[['Pantalla','text'],['Acceso','text']];rows=[['BARRA','TPV → Preparación'],['COCINA','TPV → Preparación']];note='Pantalla de preparación local. Aún no hay configuración de pantallas externas ni impresoras.'}openModal(modalTitle(name,note)+reportTable({columns,rows})+`<div class="form-actions">${['categories','families'].includes(route)?'<button class="button primary" id="module-category">+ Nueva categoría / familia</button>':''}<button class="button secondary" data-close>Cerrar</button></div>`);if($('#module-category'))$('#module-category').onclick=categoryDialog}
async function adminNavigation(b){if(b.dataset.period!==undefined){dashboardPeriod=Number(b.dataset.period);renderDashboard();return true}if(b.dataset.openReport){selectedReport=b.dataset.openReport;if(view==='home'&&dashboardData){const p=dashboardData.cards[dashboardPeriod];reportStart=p.start;reportEnd=p.end}go('reports');return true}if(b.dataset.module){openManagementModule(b.dataset.module);return true}if(b.hasAttribute('data-admin-back')){go('manage');return true}return false}
