const originalOpenModule=openManagementModule;
openManagementModule=function(name){if(managementRoutes[name]==='company'){go('company');return}if(managementRoutes[name]==='series'){go('series');return}if(managementRoutes[name]==='global_config'){go('global_config');return}if(managementRoutes[name]==='ticket_templates'){go('ticket_templates');return}if(managementRoutes[name]==='pos_profiles'){go('pos_profiles');return}if(managementRoutes[name]==='inventory'){renderInventory();return}originalOpenModule(name)};
